use super::*;
use crate::retained_clone::{RetainedCloneSource,RetainedCloneStep};
pub(crate) fn charge(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u128){assert!(p.fits(*bank));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(u64::try_from(work).unwrap()).unwrap();}
pub(crate) fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u128){assert!(work<=u128::from(PersistentList::<i64>::page_birth_work_demand().max(SealedShared::<i64>::duplicate_alias_work_demand())));charge(bank,fuel,p,work);}
pub(crate) fn debit_admit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u128){assert!(work<=u128::from(SealedShared::<u64>::birth_work_demand()));charge(bank,fuel,p,work);}
pub(crate) fn debit_admission(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u128){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();assert_eq!(p.copied_items as u64,law["admission"]["turns"].as_u64().unwrap(),"staged source admission turn count");assert_eq!(work,u128::from(law["admission"]["work"].as_u64().unwrap()),"staged source admission charges its quoted admission work");charge(bank,fuel,p,work);}
pub(crate) fn retire<T:RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..maximum{if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::effect::settle(RetainedCloneGrant{maximum_items:1,..*bank},|effect|wallet::poll(effect,|effect,reply|owner.step_into(effect.grant().maximum_copy_bytes,effect,reply))).result.unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(bank,fuel,p,owner.last_turn_work());}assert!(owner.terminal_is_empty());}
pub(crate) fn build(count:usize,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64)->PersistentList<u64>{let mut owner=PersistentListBuilder::new(count);let mut at=0;let mut row=None;for _ in 0..maximum{if owner.output_ready(){break}if owner.accepts_row()&&at<count{let turn=crate::admit_funded(at as u64,SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..*bank});let work=turn.work;let(value,p)=turn.result.map_err(|(e,_)|e).unwrap();debit_admit(bank,fuel,p,work);row=Some(value);let turn=wallet::run(RetainedCloneGrant{maximum_items:1,..*bank},|effect,reply|owner.adopt_into(&mut row,effect,reply));debit(bank,fuel,turn.result.unwrap().progress(),turn.work);at+=1;}else if owner.accepts_row(){let turn=wallet::run(RetainedCloneGrant{maximum_items:1,..*bank},|effect,reply|owner.finish_into(effect,reply));debit(bank,fuel,turn.result.unwrap().progress(),turn.work);}else{let turn=wallet::run(RetainedCloneGrant{maximum_items:1,..*bank},|effect,reply|owner.advance_into(effect,reply));debit(bank,fuel,turn.result.unwrap().progress(),turn.work);}}assert!(owner.output_ready());assert!(row.is_none());let turn=wallet::take(RetainedCloneGrant{maximum_items:1,..*bank},|output,effect,reply|owner.take_into(output,effect,reply));let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();debit(bank,fuel,p,work);{let turn=wallet::begin(RetainedCloneGrant{maximum_items:1,..*bank},|effect|owner.begin_close_paid(effect));let work=turn.work;let p=turn.result.unwrap().progress();debit(bank,fuel,p,work);}for _ in 0..maximum{if owner.terminal_is_empty(){break}let turn=crate::effect::settle(RetainedCloneGrant{maximum_items:1,..*bank},|effect|wallet::poll(effect,|effect,reply|owner.close_into(effect.grant().maximum_copy_bytes,effect,reply)));debit(bank,fuel,turn.result.unwrap().progress(),turn.work);}assert!(owner.terminal_is_empty());output}
enum Job{Set(PersistentSet<u64>),Splice(PersistentSplice<u64>)}
impl Job{fn ready(&self)->bool{match self{Self::Set(x)=>x.output_ready(),Self::Splice(x)=>x.output_ready()}}fn demand(&self,a:RetainedCloneRef<'_,PersistentList<u64>>,b:RetainedCloneRef<'_,SealedShared<u64>>)->Result<RetirementDemand,ValueError>{match self{Self::Set(x)=>x.demand(a,b),Self::Splice(x)=>x.demand(a,Some(b))}}fn advance(&mut self,a:RetainedCloneRef<'_,PersistentList<u64>>,b:RetainedCloneRef<'_,SealedShared<u64>>,g:RetainedCloneGrant)->crate::RetainedWorkOutcome{match self{Self::Set(x)=>crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|x.advance_into(a,b,effect,reply))),Self::Splice(x)=>crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|x.advance_into(a,Some(b),effect,reply)))}}fn take(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<(PersistentList<u64>,RetainedCloneProgress)>>{match self{Self::Set(x)=>wallet::take(g,|output,effect,reply|x.take_into(output,effect,reply)),Self::Splice(x)=>wallet::take(g,|output,effect,reply|x.take_into(output,effect,reply))}}fn begin_close_demand(&self)->RetirementDemand{match self{Self::Set(x)=>x.begin_close_demand(),Self::Splice(x)=>x.begin_close_demand()}}fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome{match self{Self::Set(x)=>x.begin_close_paid(effect),Self::Splice(x)=>x.begin_close_paid(effect)}}fn close(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>{match self{Self::Set(x)=>crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|x.close_into(effect.grant().maximum_copy_bytes,effect,reply))),Self::Splice(x)=>crate::effect::settle(g,|effect|wallet::poll(effect,|effect,reply|x.close_into(effect.grant().maximum_copy_bytes,effect,reply)))}}fn empty(&self)->bool{match self{Self::Set(x)=>x.terminal_is_empty(),Self::Splice(x)=>x.terminal_is_empty()}}}
#[test]fn actual_ranked_updates_keep_atomic_work_null_scratch_and_original_sources_until_paid_close(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let maximum=s["maximumTurns"].as_u64().unwrap();let count=law["inputCount"].as_u64().unwrap()as usize;let rank=law["rank"].as_u64().unwrap()as usize;let value=law["value"].as_u64().unwrap();for operation in law["operations"].as_array().unwrap(){for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap())).chain([None]){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let original=build(count,&mut bank,&mut fuel,maximum);let(original,p,work)=wallet::admit_source(original,bank,fuel);debit_admission(&mut bank,&mut fuel,p,work);let turn=crate::admit_funded(value,SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(value,p)=turn.result.map_err(|(e,_)|e).unwrap();debit_admit(&mut bank,&mut fuel,p,work);let(authored,p,work)=wallet::admit_source(value,bank,fuel);debit_admission(&mut bank,&mut fuel,p,work);let mut job=match operation.as_str().unwrap(){"set"=>Job::Set(PersistentSet::new(rank)),"insert"=>Job::Splice(PersistentSplice::new(PersistentSpliceKind::Insert,rank)),_=>Job::Splice(PersistentSplice::new(PersistentSpliceKind::Remove,rank))};let mut injected=false;for at in 0..maximum{if cut==Some(at)||job.ready(){break}let a=original.borrow();let b=authored.borrow();let d=job.demand(a,b).unwrap();for axis in 0..5{let mut g=RetainedCloneGrant{maximum_items:1,..bank};match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>g.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||job.advance(a,b,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}if d.capacity_bytes>0&&!injected{let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||job.advance(a,b,RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert!(turn.work>=1&&turn.work<=u128::from(PersistentList::<i64>::page_birth_work_demand()));fuel-=u64::try_from(turn.work).unwrap();assert!(turn.result.is_err());assert_eq!(job.demand(a,b).unwrap(),d);injected=true;continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||job.advance(a,b,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let step=turn.result.unwrap();if !job.ready(){assert!(!matches!(step,RetainedCloneStep::Complete(_)));}let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.copied_bytes<=d.copy_bytes);debit(&mut bank,&mut fuel,p,work);}if cut.is_none(){assert!(job.ready());let turn=job.take(RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();debit(&mut bank,&mut fuel,p,work);let actual:Vec<_>=output.iter().copied().collect();let mut expected:Vec<u64>=(0..count as u64).collect();match operation.as_str().unwrap(){"set"=>expected[rank]=law["value"].as_u64().unwrap(),"insert"=>expected.insert(rank,law["value"].as_u64().unwrap()),_=>{expected.remove(rank);}}assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(expected).unwrap());retire(output,&mut bank,&mut fuel,maximum);}{let turn=wallet::begin(RetainedCloneGrant{maximum_items:1,..bank},|effect|job.begin_close_paid(effect));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,&mut fuel,p,work);}for _ in 0..maximum{if job.empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||job.close(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,work);}assert!(job.empty());drop(job);retire(authored,&mut bank,&mut fuel,maximum);retire(original,&mut bank,&mut fuel,maximum);}}
}
